// Replay inputs selected by visual play, never generated by the beam search.
// Usage: node scripts/manual-replay.mjs [scripts/manual-routes/stereo-madness.json]
import assert from "node:assert/strict";
import { readFile } from "node:fs/promises";
import { chromium } from "playwright";

const route = JSON.parse(await readFile(process.argv[2] ??
  new URL("./manual-routes/stereo-madness.json", import.meta.url), "utf8"));
assert.ok(Number.isInteger(route.level) && route.level >= 1 && route.level <= 22);
assert.ok(route.segments.length > 0);
for (const [ticks, held] of route.segments) {
  assert.ok(Number.isInteger(ticks) && ticks > 0);
  assert.equal(typeof held, "boolean");
}
const browser = await chromium.launch();
try {
  const page = await browser.newPage({ viewport: { width: 1280, height: 720 } });
  const errors = [];
  page.on("pageerror", error => errors.push(error.message));
  await page.goto(`http://localhost:3222/?level=${route.level}&manual=1`);
  await page.waitForFunction(() => !!window.__play);
  // Render between segments: exercise the actual scene, triggers and camera.
  for (const [ticks, held] of route.segments) {
    const info = await page.evaluate(async ({ ticks, held }) => {
      for (let tick = 0; tick < ticks; tick++) {
        if (!window.__play.stepTick(held)) break;
      }
      await new Promise(resolve => requestAnimationFrame(() => requestAnimationFrame(resolve)));
      return window.__play.info;
    }, { ticks, held });
    assert.equal(info.dead, false, `L${route.level} died at ${info.percent.toFixed(2)}% (x=${info.x})`);
  }
  // the sim's end trigger is the completion; the results then drop ~4.3 s
  // into the ending, which renders on its own
  await page.waitForFunction(() => window.__play.info.ended, null, { timeout: 5000 });
  await page.waitForFunction(() => window.__play.info.completed, null, { timeout: 8000 });
  const info = await page.evaluate(() => window.__play.info);
  assert.equal(info.attempts, 1);
  assert.equal(info.practice, false);
  assert.deepEqual(errors, []);
  console.log(`PASS — L${route.level} manual route reaches completion, one attempt, no page errors`);
} finally {
  await browser.close();
}
